package edu.ankara.audiometer.ui.view;
import edu.ankara.audiometer.infrastructure.serial.SerialPortGateway;import javafx.scene.control.*;import javafx.scene.layout.*;import java.util.function.Consumer;
public final class SerialPanel extends TitledPane { public SerialPanel(SerialPortGateway gateway, Consumer<String> log){ setText("Serial Connection"); setCollapsible(false); ComboBox<String> ports=new ComboBox<>(); ports.getItems().addAll(gateway.listPorts()); if(!ports.getItems().isEmpty()) ports.setValue(ports.getItems().getFirst()); ComboBox<Integer> baud=new ComboBox<>(); baud.getItems().addAll(9600,19200,115200); baud.setValue(9600); Label status=new Label("Disconnected"); Button refresh=new Button("Refresh"); refresh.setOnAction(e->{ports.getItems().setAll(gateway.listPorts());}); Button connect=new Button("Connect"); connect.setOnAction(e->{ var r=gateway.connect(ports.getValue(),baud.getValue(),line->log.accept("Incoming serial: "+line)); status.setText(gateway.status().message()); log.accept(r.isOk()?"Serial connected":"Serial connection failed");}); Button disconnect=new Button("Disconnect"); disconnect.setOnAction(e->{gateway.disconnect(); status.setText("Disconnected");}); setContent(new VBox(8,new Label("Port"),ports,new Label("Baud rate"),baud,new FlowPane(6,6,refresh,connect,disconnect),status,new CheckBox("Run without hardware using Simulation Mode"))); } }
